mapper.select:

WHERE R.DEL_YN = 'N'

  AND R.REC_CATEGORY_CD = #{recCategoryCd}

ORDER BY R.SORT_ORDER ASC, R.CONTENT_REC_HOUSE_SN DESC

mapper.update:
UPDATE CONTENT_REC_HOUSE
   SET EXPOSE_YN = #{exposeYn},
       MDFCN_DT  = UTC_TIMESTAMP(6),
       MDFR_SN   = #{mdfrSn}
 WHERE CONTENT_REC_HOUSE_SN = #{contentRecHouseSn}
   AND DEL_YN = 'N'

UPDATE CONTENT_REC_HOUSE
   SET SORT_ORDER = #{sortOrder},
       MDFCN_DT   = UTC_TIMESTAMP(6),
       MDFR_SN    = #{mdfrSn}
 WHERE CONTENT_REC_HOUSE_SN = #{contentRecHouseSn}
   AND DEL_YN = 'N'

UPDATE CONTENT_REC_HOUSE
   SET DEL_YN   = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN  = #{mdfrSn}
 WHERE CONTENT_REC_HOUSE_SN = #{contentRecHouseSn}
   AND DEL_YN = 'N'
